export interface Preferences {
  readonly language: string;
  readonly accent: string;
}

export class PreferenceManager {
  private readonly supported: Set<string>;
  private language: string;
  private accent: string;

  constructor(supportedLanguages: readonly string[], fallbackLanguage: string, fallbackAccent: string) {
    const normalized = supportedLanguages.map((value) => value.trim());
    if (normalized.length === 0 || normalized.some((value) => value.length === 0) || new Set(normalized).size !== normalized.length) {
      throw new RangeError("Invalid supported languages");
    }
    this.supported = new Set(normalized);
    this.language = fallbackLanguage.trim();
    const accent = PreferenceManager.normalizeAccent(fallbackAccent);
    if (!this.supported.has(this.language) || accent === undefined) {
      throw new RangeError("Invalid fallbacks");
    }
    this.accent = accent;
  }

  setLanguage(language: string): boolean {
    const normalized = language.trim();
    if (!this.supported.has(normalized)) return false;
    this.language = normalized;
    return true;
  }

  setAccent(accent: string): boolean {
    const normalized = PreferenceManager.normalizeAccent(accent);
    if (normalized === undefined) return false;
    this.accent = normalized;
    return true;
  }

  current(): Preferences {
    return { language: this.language, accent: this.accent };
  }

  serialize(): string {
    return JSON.stringify({ language: this.language, accent: this.accent });
  }

  restore(serialized: string): boolean {
    try {
      const parsed: unknown = JSON.parse(serialized);
      if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return false;
      const value = parsed as Record<string, unknown>;
      if (typeof value.language !== "string" || typeof value.accent !== "string") return false;
      const language = value.language.trim();
      const accent = PreferenceManager.normalizeAccent(value.accent);
      if (accent === undefined) return false;
      this.language = language;
      this.accent = accent;
      return true;
    } catch {
      return false;
    }
  }

  private static normalizeAccent(value: string): string | undefined {
    return /^#[0-9a-fA-F]{6}$/.test(value) ? value.toUpperCase() : undefined;
  }
}

