import { PreferenceManager } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(action: () => void, message: string): void {
  try { action(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

rangeError(() => new PreferenceManager([], 'en', '#112233'), 'empty supported list');
rangeError(() => new PreferenceManager(['en', ' '], 'en', '#112233'), 'blank supported language');
rangeError(() => new PreferenceManager(['en', ' en '], 'en', '#112233'), 'normalized duplicate language');
rangeError(() => new PreferenceManager(['en'], 'fr', '#112233'), 'unsupported fallback language');
rangeError(() => new PreferenceManager(['en'], 'en', '112233'), 'accent missing hash');
rangeError(() => new PreferenceManager(['en'], 'en', '#12345G'), 'accent with non-hex digit');
rangeError(() => new PreferenceManager(['en'], 'en', ' #112233 '), 'accent is not trimmed');

const supported = [' en ', 'fr', '日本語'];
const manager = new PreferenceManager(supported, ' en ', '#a1b2c3');
supported[0] = 'changed';
let current = manager.current();
equal(current.language, 'en', 'fallback language normalized');
equal(current.accent, '#A1B2C3', 'fallback accent uppercased');
equal(manager.setLanguage(' fr '), true, 'supported trimmed language accepted');
equal(manager.current().language, 'fr', 'language updated');
equal(manager.setLanguage('changed'), false, 'supported input array was copied');
equal(manager.setLanguage(''), false, 'blank language rejected');
equal(manager.setLanguage('de'), false, 'unsupported language rejected');
equal(manager.current().language, 'fr', 'failed language update preserves state');

equal(manager.setAccent('#00ffAa'), true, 'valid mixed-case accent accepted');
equal(manager.current().accent, '#00FFAA', 'accent normalized uppercase');
equal(manager.setAccent('#FFF'), false, 'short accent rejected');
equal(manager.setAccent(' #001122'), false, 'accent whitespace rejected');
equal(manager.setAccent('#00112233'), false, 'long accent rejected');
equal(manager.current().accent, '#00FFAA', 'failed accent update preserves state');

equal(manager.serialize(), '{"language":"fr","accent":"#00FFAA"}', 'serialization is compact and ordered');
const first = manager.current();
const second = manager.current();
assert(first !== second, 'current returns fresh objects');
(first as { language: string; accent: string }).language = 'tampered';
equal(manager.current().language, 'fr', 'current result cannot mutate state');

const invalidRestores = [
  '', '{', 'null', '[]', '"text"', '{}',
  '{"language":"fr"}', '{"accent":"#112233"}',
  '{"language":1,"accent":"#112233"}',
  '{"language":"de","accent":"#112233"}',
  '{"language":"en","accent":"#xyzxyz"}',
];
for (const serialized of invalidRestores) {
  equal(manager.restore(serialized), false, `invalid restore rejected: ${serialized}`);
  equal(manager.serialize(), '{"language":"fr","accent":"#00FFAA"}', 'failed restore is atomic');
}

equal(manager.restore('{"language":" 日本語 ","accent":"#abcdef","extra":true}'), true, 'valid restore permits extra properties');
equal(manager.current().language, '日本語', 'restored language normalized');
equal(manager.current().accent, '#ABCDEF', 'restored accent normalized');

